// Guide pages (/docs/): makes the samples live. Files shown with a name
// above them can be edited, and each output block gets a Run button that runs
// its command in the browser with the WebAssembly build of ok, using the
// files of its section as they are now. The pages themselves are generated by
// crates/okdocs from docs/*.md.

import { appendAnsi, parseCommand, runOk, warm } from "/ok-runner.js";

// The contents list starts open so it shows without JavaScript; on narrow
// screens it sits above the page and starts closed.
const toc = document.querySelector("details.toc");
if (toc && matchMedia("(max-width: 860px)").matches) toc.open = false;

for (const code of document.querySelectorAll(".sample-file code")) {
  code.contentEditable = "plaintext-only";
  code.spellcheck = false;
  code.setAttribute("aria-label", `Contents of ${code.closest("figure").dataset.file}, editable`);
}

// The files an output block runs with: the named files of its section that
// come before it, later ones replacing earlier ones with the same name.
function filesFor(figure) {
  const files = {};
  for (const f of document.querySelectorAll(`.sample-file[data-group="${figure.dataset.group}"]`)) {
    if (f.compareDocumentPosition(figure) & Node.DOCUMENT_POSITION_FOLLOWING) {
      files[f.dataset.file] = f.querySelector("code").textContent;
    }
  }
  return files;
}

for (const figure of document.querySelectorAll(".sample-out")) {
  if (figure.dataset.browser === "no") continue;
  const caption = figure.querySelector("figcaption");
  const out = figure.querySelector("pre.out");
  const status = document.createElement("span");
  status.className = "run-status";
  const button = document.createElement("button");
  button.type = "button";
  button.className = "run";
  button.textContent = "Run";
  button.title = "Run this command in your browser; edit the files above first if you like";
  caption.append(status, button);
  button.addEventListener("pointerenter", warm, { once: true });
  button.addEventListener("focus", warm, { once: true });
  button.addEventListener("click", async () => {
    let parsed;
    try {
      parsed = parseCommand(figure.dataset.run);
    } catch (e) {
      status.textContent = e.message;
      return;
    }
    button.disabled = true;
    status.textContent = "running…";
    const started = performance.now();
    // The same environment the guide's tests use: projects are trusted, and
    // the trust store lives in the run's own directory (the browser has no
    // home directory).
    const result = await runOk({ args: parsed.args, env: { OK_TRUST: "1", OK_CONFIG_DIR: ".ok-config", ...parsed.env }, files: filesFor(figure) });
    button.disabled = false;
    if (result.busy) {
      status.textContent = "another run is still going";
      return;
    }
    out.replaceChildren();
    for (const [stream, text] of result.out) appendAnsi(out, text, stream);
    if (result.crash) {
      appendAnsi(out, `\n${result.crash}\n`, "err red");
      status.textContent = "stopped";
      return;
    }
    status.textContent = `exit ${result.code} · ${Math.round(performance.now() - started)} ms`;
  });
}
